import React, { useState } from "react";
import Navbar from "../../components/Navbar";
import { api } from "../../utils/api";
import { setAuth } from "../../utils/auth";
import { useNavigate } from "react-router-dom";

export default function AdminLogin() {
  const nav = useNavigate();
  const [loading, setLoading] = useState(false);

  const [email, setEmail] = useState("admin@cyberraksha.com");
  const [password, setPassword] = useState("Admin@123");

  async function login(e) {
    e.preventDefault();
    setLoading(true);

    try {
      const res = await api.post("/api/auth/login", { email, password });
      setAuth(res.data.token, res.data.user);
      nav("/admin");
    } catch (err) {
      alert(err?.response?.data?.message || "Login failed");
    } finally {
      setLoading(false);
    }
  }

  return (
    <div className="min-h-screen bg-gray-50">
      <Navbar />

      <div className="max-w-md mx-auto px-4 py-16">
        <div className="bg-white rounded-3xl shadow p-6">
          <h2 className="text-2xl font-black">Admin Login</h2>
          <p className="text-sm text-gray-600 mt-1">
            Login for SOC dashboard access.
          </p>

          <form onSubmit={login} className="mt-6 space-y-4">
            <input
              className="border rounded-2xl px-4 py-3 w-full"
              placeholder="Email"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
            />

            <input
              className="border rounded-2xl px-4 py-3 w-full"
              placeholder="Password"
              type="password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
            />

            <button
              disabled={loading}
              className="w-full px-5 py-3 rounded-2xl bg-gray-900 text-white font-semibold disabled:opacity-60"
            >
              {loading ? "Logging in..." : "Login"}
            </button>

            <div className="text-xs text-gray-600">
              Default admin is created by backend seed.
              <br />
              Email: <b>admin@cyberraksha.com</b> | Password: <b>Admin@123</b>
            </div>
          </form>
        </div>
      </div>
    </div>
  );
}
